-- The Quran's printed topical index: the alphabetical subject index bound into
-- the back of Quran, The Final Testament. One parent row per entry ("Abraham",
-- "Alimony"), child rows for its sub-entries ("monotheist", "tested"), and a
-- reference row per verse citation.
--
-- Seeded from db/seeds/quran_topic_index_<lang>.json, generated by
-- scripts/topic_index/build.mjs out of the seven HTML pages at
-- masjidtucson.org/quran/index/qindex_*.html (retrieved 2026-08-19). See
-- db/topic_index.go for the loader.
--
-- NAMING: "quran index" is already taken in this repo and means something else.
-- assets/source_data/ws_quran_index_rows.sql is a legacy verse-enumeration table
-- (verse_index, verse_id, chapter_number, verse_number) consumed by
-- api/cmd/seed.go. These tables are the *topical* index — hence topic_index_*.
-- The user-facing route is /quran/index.
--
-- Three tables on purpose. Compare 029_site_documents.sql, which folds sections
-- into one table because most of its rows are page-level and a split would double
-- the row count for the common case. Here the shape is genuinely nested: 1,217
-- entries carry 987 sub-entries and 13,557 verse references between them. Folding
-- that flat would repeat every entry title across an average of eleven rows and
-- make "list letter A" a DISTINCT over thousands of references instead of an index
-- scan over thirty-five.
--
-- Sub-entry LABELS are nonetheless denormalized onto the parent as
-- subentry_text, purely so search_tsv can weight them without a join — the same
-- trade 029 makes with its repeated `title`. The labels are short ("chosen by
-- God"), so the cost is a few KB across the whole table.
--
-- VERSE NUMBERS ARE 1-BASED, as printed. This differs from public.verses, whose
-- verse_index column is 0-based (vi 0 is the Basmalah, vi 1 is verse 1). Do not
-- join these columns without converting. 1-based was chosen because every
-- consumer is a display or a link: the frontend's ?verse=N is 1-based too.
--
-- References are NOT foreign keys to public.verses. The printed index contains a
-- handful of typographic errors (27:2244, 9:128 in a 127-verse chapter) which
-- scripts/topic_index/build.mjs quarantines and reports; a FK would instead fail
-- the whole seed transaction on the next one it finds. Range ends are stored
-- rather than expanded — "7:65-72" is one row, not eight, and the frontend links
-- to the range start.
--
-- `lang` is deliberately not a foreign key to `languages`, matching the choice
-- site_documents.lang and library_documents.lang make: these are index editions,
-- and only English exists today.
--
-- No embedding column. The corpus is 1,217 short titles; a GIN index answers in
-- microseconds and an entry title carries no prose to embed. When semantic
-- lookup is wanted:
--   ALTER TABLE public.topic_index_entries
--       ADD COLUMN IF NOT EXISTS embedding public.vector(512);
--   CREATE INDEX IF NOT EXISTS topic_index_entries_embedding_hnsw
--       ON public.topic_index_entries USING hnsw (embedding public.vector_cosine_ops);
-- The trigram index below is the one that earns its place now: "abrogaton",
-- "alimoney" and "sheeba" are the realistic failure mode.
--
-- Idempotent: safe to re-run.

CREATE TABLE IF NOT EXISTS public.topic_index_entries (
    id            INT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,

    lang          TEXT     NOT NULL,             -- index edition: 'en' today
    letter        CHAR(1)  NOT NULL,             -- the printed A-Z section; there is no X
    title         TEXT     NOT NULL,             -- 'Abraham', 'Almighty,God is'
    sort_key      TEXT     NOT NULL,             -- lowercased, punctuation-stripped
    slug          TEXT     NOT NULL,             -- URL fragment: /quran/index?letter=A#abraham
    position      INT      NOT NULL,             -- printed order within the edition

    -- '(see also Hood)' / 'see Covenant, Promises' lifted out of the title. These
    -- are other entry titles in the same edition, matched by sort_key at read
    -- time rather than stored as ids: the printed text does not always spell a
    -- target exactly as that entry's own title.
    cross_refs    TEXT[]   NOT NULL DEFAULT '{}',

    -- Sub-entry labels, space-joined. Denormalized for search_tsv only; the rows
    -- in topic_index_subentries remain the source of truth. Rebuilt on re-seed.
    subentry_text TEXT     NOT NULL DEFAULT '',

    -- 'simple' like every other content tsvector in this schema: exact tokens, no
    -- stemming surprises across languages. setweight puts the entry title in band
    -- A, sub-entry labels in B and cross-references in C, so ts_rank_cd does the
    -- field weighting instead of a hand-rolled score (same as site_documents).
    search_tsv    tsvector GENERATED ALWAYS AS (
        setweight(to_tsvector('simple', coalesce(title, '')),                        'A') ||
        setweight(to_tsvector('simple', coalesce(subentry_text, '')),                'B') ||
        setweight(to_tsvector('simple', array_to_string(cross_refs, ' ')),           'C')
    ) STORED,

    -- Trigram haystack for the fuzzy fallback leg. Titles and labels only.
    fuzzy_text    TEXT GENERATED ALWAYS AS (
        coalesce(title, '') || ' ' || coalesce(subentry_text, '')
    ) STORED,

    updated_at    timestamptz NOT NULL DEFAULT now(),

    CONSTRAINT topic_index_entries_letter_check CHECK (letter ~ '^[A-Z]$')
);

-- One entry per (edition, sort key). build.mjs folds the source's split blocks
-- (Moses, Satan's appear twice in print) before emitting, so a collision here
-- means the generator regressed.
CREATE UNIQUE INDEX IF NOT EXISTS topic_index_entries_identity_idx
    ON public.topic_index_entries (lang, sort_key);

-- Drives the letter page: an index scan over one letter in printed order.
CREATE INDEX IF NOT EXISTS topic_index_entries_letter_idx
    ON public.topic_index_entries (lang, letter, position);

CREATE INDEX IF NOT EXISTS topic_index_entries_search_tsv_idx
    ON public.topic_index_entries USING GIN (search_tsv);

CREATE INDEX IF NOT EXISTS topic_index_entries_fuzzy_trgm_idx
    ON public.topic_index_entries USING GIN (fuzzy_text public.gin_trgm_ops);


CREATE TABLE IF NOT EXISTS public.topic_index_subentries (
    id         INT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    entry_id   INT  NOT NULL REFERENCES public.topic_index_entries (id) ON DELETE CASCADE,
    label      TEXT NOT NULL,          -- 'monotheist', 'builds Kaaba'
    position   INT  NOT NULL           -- printed order within the entry
);

CREATE UNIQUE INDEX IF NOT EXISTS topic_index_subentries_identity_idx
    ON public.topic_index_subentries (entry_id, position);


CREATE TABLE IF NOT EXISTS public.topic_index_refs (
    id             INT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    entry_id       INT      NOT NULL REFERENCES public.topic_index_entries (id) ON DELETE CASCADE,

    -- NULL when the reference hangs off the entry itself rather than a sub-entry.
    subentry_id    INT      REFERENCES public.topic_index_subentries (id) ON DELETE CASCADE,

    chapter_number SMALLINT NOT NULL,
    verse_start    SMALLINT NOT NULL,  -- 1-based; 0 is the Basmalah
    verse_end      SMALLINT NOT NULL,  -- equals verse_start for a single verse
    display        TEXT     NOT NULL,  -- '7:65-72' — rendered verbatim
    position       INT      NOT NULL,  -- printed order within entry or sub-entry

    CONSTRAINT topic_index_refs_chapter_check CHECK (chapter_number BETWEEN 1 AND 114),
    CONSTRAINT topic_index_refs_range_check   CHECK (verse_end >= verse_start AND verse_start >= 0)
);

-- subentry_id is NULL on entry-level references, so a plain UNIQUE would admit
-- duplicates; coalesce makes NULL collide like a real value (the same trick
-- site_documents_identity_idx and library_documents_identity_idx use).
CREATE UNIQUE INDEX IF NOT EXISTS topic_index_refs_identity_idx
    ON public.topic_index_refs (entry_id, COALESCE(subentry_id, 0), position);

-- Reverse lookup: which topics cite this verse. Ranges mean the query is
-- `chapter_number = $1 AND verse_start <= $2 AND verse_end >= $2`, so the index
-- narrows on chapter and start and filters the rest.
CREATE INDEX IF NOT EXISTS topic_index_refs_verse_idx
    ON public.topic_index_refs (chapter_number, verse_start, verse_end);

CREATE INDEX IF NOT EXISTS topic_index_refs_subentry_idx
    ON public.topic_index_refs (subentry_id);
